import * as C from './core.7a72500fb3d4.mjs';
import {symbolSVG} from './symbols.7a72500fb3d4.mjs';
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const h=escapeHTML;
export function entrySelection(data,bookID,flow,selected){
  const parents=data.categories.filter(c=>c.bookID===bookID&&c.flow===flow&&!c.parentID);
  const category=data.categories.find(c=>c.id===selected&&c.bookID===bookID&&c.flow===flow)||parents[0];
  const parent=category&&(data.categories.find(c=>c.id===category.parentID)||category);
  return {parents,category,parent,children:parent?data.categories.filter(c=>c.parentID===parent.id):[]};
}
export function entryCategoryPicker(data,bookID,flow,selected){
  const {parents,category,parent,children}=entrySelection(data,bookID,flow,selected);
  return `<div class="entry-category-head"><h3>选择分类</h3><span class="selection-caption" aria-live="polite">${category?h(C.categoryPath(data,category.id)):'暂无分类'}</span></div>${parents.length?`<div class="parent-grid" aria-label="一级分类">${parents.map(c=>`<button type="button" class="parent-choice ${parent?.id===c.id?'active':''}" data-action="entry-parent" data-id="${c.id}" aria-label="${h(c.name)}" aria-pressed="${parent?.id===c.id}"><span class="parent-symbol">${symbolSVG(c.icon)}</span><span>${h(c.name)}</span></button>`).join('')}</div>`:`<p class="settings-note">暂无${flow==='income'?'收入':'支出'}分类，请先到「账本」新增分类。</p>`}${children.length?`<div class="child-picker"><p>二级分类</p><div class="child-grid" aria-label="二级分类">${[{id:parent.id,name:'不细分',icon:'square.grid.2x2'},...children].map(c=>`<button type="button" class="child-choice ${category.id===c.id?'active':''}" data-action="entry-child" data-id="${c.id}" aria-label="${h(c.name)}" aria-pressed="${category.id===c.id}">${symbolSVG(c.icon)}<span>${h(c.name)}</span></button>`).join('')}</div></div>`:''}`;
}
export function entryForm(data,bookID,entry){
  const flow=entry?.flow||'expense',selection=entrySelection(data,bookID,flow,entry?.categoryID),categoryID=selection.category?.id||'';
  return `<form data-kind="entry" class="entry-form" data-id="${entry?.id||''}"><div class="entry-scroll"><input type="hidden" name="flow" value="${flow}"><input type="hidden" name="categoryID" value="${categoryID}"><div class="segments entry-flow">${[['expense','支出'],['income','收入']].map(([id,name])=>`<button type="button" data-action="entry-flow" data-flow="${id}" class="${flow===id?'active':''}" aria-pressed="${flow===id}">${name}</button>`).join('')}</div><section class="card amount-card"><label class="amount-label" for="entry-amount">${flow==='expense'?'支出':'收入'}金额</label><div class="amount-line"><span>¥</span><input id="entry-amount" class="num" name="amount" inputmode="decimal" autocomplete="off" placeholder="0.00" required value="${entry?C.money(entry.cents,false):''}" aria-label="金额"></div></section><section class="card entry-category-card" id="entry-categories">${entryCategoryPicker(data,bookID,flow,categoryID)}</section><section class="card entry-details"><label class="detail-row"><span>账本</span><select name="bookID" data-entry-book aria-label="账本">${data.books.map(b=>`<option value="${b.id}" ${b.id===bookID?'selected':''}>${h(b.name)}</option>`).join('')}</select></label><label class="detail-row"><span>日期</span><input name="day" type="date" min="1900-01-01" max="2200-12-31" value="${entry?.day||C.dayString()}" aria-label="日期" required></label><label class="entry-note"><span>备注</span><textarea name="note" maxlength="500" rows="2" placeholder="例如：和朋友的一顿晚餐" aria-label="备注">${h(entry?.note||'')}</textarea></label><small class="note-count">${(entry?.note||'').length}/500</small></section>${entry?`<button type="button" class="delete-entry-link danger" data-action="delete-entry" data-id="${entry.id}">删除这笔记录</button>`:''}<p class="form-error" role="alert"></p></div><div class="entry-save"><button class="primary" type="submit">${entry?'保存修改':'保存记录'}</button><button type="button" class="entry-cancel" data-action="close">取消</button></div></form>`;
}
const handle=c=>`<button class="drag-handle" data-action="choose-move" data-drag-id="${c.id}" data-id="${c.id}" aria-label="拖动${h(c.name)}" title="拖动或点按选择移动">☰</button>`;
function dropSlot(title,parentID='',beforeID='',selected=''){
  return `<button class="category-drop-slot ${selected?'move-available':''}" data-action="place-category" data-drop-parent="${parentID}" data-drop-before="${beforeID}"><span>↧</span> ${h(title)}</button>`;
}
function sortRow(c,nextID,selected){
  const destination=c.parentID?`data-drop-parent="${c.parentID}" data-drop-before="${c.id}" data-drop-after="${nextID||''}"`:'';
  const label=`<span class="sort-symbol">${symbolSVG(c.icon)}</span><span class="sort-name">${h(c.name)}</span>`;
  return `<div class="category-sort-row ${c.parentID?'sort-child':''} ${selected===c.id?'move-selected':''}" ${destination}>${c.parentID?`<button class="sort-target" data-action="place-category" ${destination} aria-label="放到${h(c.name)}前面">${label}</button>`:`<span class="sort-target">${label}</span>`}${handle(c)}</div>`;
}
export function categoryManagement(data,bookID,flow,{arranging=false,selectedMoveID=''}={}){
  const book=data.books.find(b=>b.id===bookID),parents=data.categories.filter(c=>c.bookID===bookID&&c.flow===flow&&!c.parentID),moving=data.categories.find(c=>c.id===selectedMoveID);
  return `<section class="card category-management" id="category-management"><div class="section-head"><div><h2>分类管理</h2><p class="category-subtitle">${h(book.name)} · 点击分类可编辑</p></div></div><div class="category-toolbar"><button class="text-button" data-action="toggle-arranging">${arranging?'✓ 完成整理':'⇅ 拖动整理'}</button><button class="text-button" data-action="match-icons">✧ 匹配图标</button></div>${arranging?`<p class="arrange-hint" role="status">${moving?`已选「${h(moving.name)}」，请点击放置位置。`:'按住右侧拖动柄移动，也可点按拖动柄后点击放置位置。一级分类可连同子分类排序，二级分类可调整顺序、归属或提升为一级。'}</p>`:''}<div class="category-flow-row"><div class="segments">${[['expense','支出'],['income','收入']].map(([id,name])=>`<button data-action="category-flow" data-flow="${id}" class="${flow===id?'active':''}" aria-pressed="${flow===id}">${name}</button>`).join('')}</div><button class="text-button" data-action="category-editor">＋ 一级分类</button></div>${parents.length?parents.map(parent=>{const children=data.categories.filter(c=>c.parentID===parent.id);return arranging?`${dropSlot(`放到「${parent.name}」前 · 一级`,'',parent.id,selectedMoveID)}<div class="category-sort-group">${sortRow(parent,null,selectedMoveID)}${children.map((c,i)=>sortRow(c,children[i+1]?.id,selectedMoveID)).join('')}${dropSlot(`移入「${parent.name}」末尾 · 二级`,parent.id,'',selectedMoveID)}</div>`:`<div class="category-group"><div class="category-group-head"><button class="parent-edit" data-action="category-editor" data-id="${parent.id}" aria-label="编辑${h(parent.name)}"><span class="category-parent-badge">${symbolSVG(parent.icon)}</span><strong>${h(parent.name)}</strong><span class="edit-hint">✎</span></button><button class="text-button add-child" data-action="category-editor" data-parent="${parent.id}" aria-label="为${h(parent.name)}新增二级分类">＋ 二级分类</button></div>${children.length?`<div class="management-children">${children.map(c=>`<button data-action="category-editor" data-id="${c.id}" class="management-chip" aria-label="编辑${h(c.name)}">${symbolSVG(c.icon)}<span>${h(c.name)}</span></button>`).join('')}</div>`:''}</div>`;}).join(''):'<p class="settings-note">还没有分类，点击「＋ 一级分类」开始建立。</p>'}${arranging?dropSlot('移到一级分类末尾','','',selectedMoveID):''}</section>`;
}
